  @override
  void initState() {
    super.initState();

    // Слушаем изменения в поле поиска
    _searchController.addListener(_onSearchChanged);
  }

  void _onSearchChanged() {
    // Вызывается при каждом изменении текста
    print('Поиск: ${_searchController.text}');
  }

  @override
  void dispose() {
    // ВАЖНО: Освобождаем ресурсы!
    _nameController.dispose();
    _emailController.dispose();
    _searchController.dispose();
    super.dispose();
  }

  void _fillWithSampleData() {
    setState(() {
      _nameController.text = 'Асет Нурланов';
      _emailController.text = 'aset@example.kz';
    });
